export function OgHindiText({
  phrase,
  fontSize = 20,
  color = "#FFFFFF",
  style,
}: {
  phrase: OgHindiPhraseKey;
  fontSize?: number;
  color?: string;
  style?: React.CSSProperties;
}) {
  const g = HINDI_SVG_GLYPHS[phrase];
  const w = Math.ceil((g.width / 100) * fontSize);
  const h = Math.ceil((g.height / 100) * fontSize);

  return (
    <svg
      width={w}
      height={h}
      viewBox={`0 0 ${g.width} ${g.height}`}
      style={{ flexShrink: 0, display: "flex", ...style }}
    >
      <path d={g.d} fill={color} />
    </svg>
  );
}
